import { Effect } from "effect";
import { SqlClient } from "effect/sql";

/**
 * Local users: one row per Keycloak account that has logged in at least
 * once, created or updated on every successful login.
 *
 * Keycloak owns the identity. This table only mirrors the profile claims of
 * the last login and gives each user a stable id of our own.
 */
export default Effect.gen(function* () {
  const sql = yield* SqlClient.SqlClient;

  // id is generated by the application (UUID v4), so the aggregate has its
  // identity before it is stored. subject is the OIDC `sub`: unique and never
  // reassigned within the issuer, and the key a login is matched by (the
  // application inserts with ON CONFLICT (subject) DO NOTHING). Its check
  // mirrors the oidc lib's `Subject` schema: non-empty, at most 255
  // characters.
  //
  // username (`preferred_username`) is a display hint only, and email is not
  // unique either: Keycloak can change or share both, so nothing may rely on
  // them to identify a user.
  //
  // The timestamps have no default: the application sets them from the
  // Effect clock, so tests control time. updated_at changes when the profile
  // changes, last_login_at on every login.
  //
  // No indexes beyond the primary key and the unique subject: logins look
  // users up by subject, everything else by id.
  yield* sql`
    CREATE TABLE users (
      id uuid NOT NULL,
      subject text NOT NULL,
      username text NULL,
      name text NULL,
      email text NULL,
      email_verified boolean NOT NULL DEFAULT false,
      created_at timestamptz NOT NULL,
      updated_at timestamptz NOT NULL,
      last_login_at timestamptz NOT NULL,
      CONSTRAINT users_id_pkey PRIMARY KEY (id),
      CONSTRAINT users_subject_key UNIQUE (subject),
      CONSTRAINT users_subject_check
        CHECK (char_length(subject) BETWEEN 1 AND 255)
    )
  `;
});
